/**
 * workspace-controller — multi-workspace lifecycle orchestrator.
 *
 * Subscribes to `workspace:*_requested` events on the bus (routed from
 * client WebSocket messages by client-message-router), mutates the
 * `workspaces` table via registry-service, and emits `workspace:*` result
 * events that workspace-broadcaster fans out to clients.
 *
 * At `start()` time:
 *   1. Gate every registered workspace through the view-readiness owner.
 *   2. auditRegistryAvailability() — warn about unavailable registered rows.
 *   3. restoreLastActive() — read system_config.last_active_workspace_id
 *      and set module-level activeWorkspaceId.
 *   4. Subscribe request handlers.
 *
 * Module-level activeWorkspaceId is sufficient for today's single-tab
 * reality (see WORKSPACE_CONTROLLER_SPEC §6). Per-connection active state
 * is future work.
 *
 * The controller also caches the active workspace row (`activeWorkspace`)
 * so sync callers (HTTP routes, file-explorer symlink check, boot
 * pipeline) can resolve `repo_path` without an async DB hop. The cache is
 * the source of truth that `server.js#getProjectRoot()` reads from.
 */

const fs = require('fs');
const path = require('path');

const { on, emit } = require('../event-bus');
const { getDb } = require('../db');
const pathService = require('./path-service');
const registry = require('./registry-service');
const bootstrap = require('./bootstrap-service');
const createService = require('./create-service');
const { createWorkspaceRibbonHandlers } = require('./workspace-ribbon');
const viewReadiness = require('../views/readiness-runtime');
const { publishElectronWorkspaceBinding } = require('./electron-binding-channel');

let activeWorkspaceId = null;
let activeWorkspace = null; // cached registry row, kept in lockstep with activeWorkspaceId so sync callers (HTTP routes, file-explorer symlink check, boot pipeline) can resolve repo_path without awaiting a DB query
let activeWorkspaceBindingRevision = 0;
let lifecycleTail = Promise.resolve();

const ribbonHandlers = createWorkspaceRibbonHandlers({
  registry,
  emit,
  getActiveWorkspaceId: () => activeWorkspaceId,
  setActiveWorkspace,
  writeLastActive,
});

async function start() {
  if (!viewReadiness.hasInstalledViewReadinessOwner()) {
    const { createViewReadinessCoordinator } = require('../views/readiness-coordinator');
    const { createViewRelocationService } = require('../views/relocation-service');
    const { getLocalMachineName } = require('./ai-paths');
    viewReadiness.installViewReadinessOwner(createViewReadinessCoordinator({
      migrationService: createViewRelocationService({ db: getDb() }),
      machineIdentity: getLocalMachineName(),
    }));
  }
  await viewReadiness.ensureRegisteredWorkspaceReadiness(await registry.list());
  await auditRegistryAvailability();
  await restoreLastActive();
  publishActiveWorkspaceBinding();

  on('workspace:add_requested', (event) => enqueueWorkspaceLifecycle(
    () => handleAddRequested(event),
  ));
  on('workspace:switch_requested', (event) => enqueueWorkspaceLifecycle(
    () => handleSwitchRequested(event),
  ));
  on('workspace:remove_requested', (event) => enqueueWorkspaceLifecycle(
    () => handleRemoveRequested(event),
  ));
  on('workspace:ribbon_remove_requested', (event) => enqueueWorkspaceLifecycle(
    () => ribbonHandlers.handleRibbonRemoveRequested(event),
  ));
  on('workspace:ribbon_add_requested', (event) => enqueueWorkspaceLifecycle(
    () => ribbonHandlers.handleRibbonAddRequested(event),
  ));
  on('workspace:ribbon_reorder_requested', (event) => enqueueWorkspaceLifecycle(
    () => ribbonHandlers.handleRibbonReorderRequested(event),
  ));
  on('workspace:create_requested', (event) => enqueueWorkspaceLifecycle(
    () => handleCreateRequested(event),
  ));

  console.log('[WorkspaceController] Started (active: ' + (activeWorkspaceId || 'none') + ')');
  emit('workspace:controller_ready');
}

function enqueueWorkspaceLifecycle(operation) {
  const current = lifecycleTail
    .catch(() => undefined)
    .then(operation);
  lifecycleTail = current;
  return current;
}

function runInWorkspaceLifecycle(operation) {
  if (typeof operation !== 'function') {
    return Promise.reject(new TypeError('workspace lifecycle operation is required'));
  }
  return enqueueWorkspaceLifecycle(operation);
}

function getLaunchStatus(workspace) {
  const repoPath = workspace.repo_path || workspace.repoPath;
  if (!isDirectory(repoPath)) {
    return { available: false, reason: 'path_missing' };
  }
  if (!bootstrap.isValidWorkspaceRoot(repoPath)) {
    return { available: false, reason: 'invalid_structure' };
  }
  return { available: true, reason: null };
}

async function auditRegistryAvailability() {
  const rows = await registry.list();
  let unavailable = 0;

  for (const row of rows) {
    const status = getLaunchStatus(row);
    if (status.available) continue;

    console.warn(
      '[WorkspaceController] Registered workspace unavailable at launch (' +
        row.id +
        '): ' +
        status.reason
    );
    emit('workspace:unavailable_at_launch', { workspaceId: row.id, reason: status.reason });
    unavailable += 1;
  }

  console.log(
    '[WorkspaceController] Launch registry audit: ' +
      rows.length +
      ' workspaces, ' +
      unavailable +
      ' unavailable'
  );
}

async function restoreLastActive() {
  const row = await getDb()('system_config').where('key', 'last_active_workspace_id').first();
  const candidateId = row ? row.value : null;

  if (candidateId) {
    const existing = await registry.getById(candidateId);
    if (existing && getLaunchStatus(existing).available) {
      activeWorkspaceId = candidateId;
      activeWorkspace = existing;
      console.log('[WorkspaceController] Restored workspace: ' + candidateId);
      return;
    }
    if (existing) {
      const status = getLaunchStatus(existing);
      console.warn(
        '[WorkspaceController] Last active workspace unavailable at launch (' +
          candidateId +
          '): ' +
          status.reason
      );
    }
  }

  if (row && !candidateId) {
    activeWorkspaceId = null;
    activeWorkspace = null;
    console.log('[WorkspaceController] Restored workspace: none');
    return;
  }

  // Candidate is unavailable or was never set — fall back to the first
  // launchable row without removing any registrations.
  const all = await registry.list();
  const fallback = all.find((workspace) => getLaunchStatus(workspace).available) || null;
  if (fallback) {
    activeWorkspaceId = fallback.id;
    activeWorkspace = fallback;
    await writeLastActive(activeWorkspaceId);
    console.log('[WorkspaceController] Restored workspace: ' + activeWorkspaceId + ' (fallback)');
  } else {
    activeWorkspaceId = null;
    activeWorkspace = null;
    console.log('[WorkspaceController] No workspaces');
  }
}

async function writeLastActive(workspaceId) {
  await getDb()('system_config')
    .insert({
      key: 'last_active_workspace_id',
      value: workspaceId == null ? '' : workspaceId,
      updated_at: Date.now(),
    })
    .onConflict('key')
    .merge(['value', 'updated_at']);
}

function setActiveWorkspace(workspaceId, workspace) {
  activeWorkspaceId = workspaceId;
  activeWorkspace = workspace;
  return publishActiveWorkspaceBinding();
}

function publishActiveWorkspaceBinding() {
  if (activeWorkspaceBindingRevision >= Number.MAX_SAFE_INTEGER) {
    throw new Error('electron_workspace_binding_revision_exhausted');
  }
  activeWorkspaceBindingRevision += 1;
  publishElectronWorkspaceBinding(
    activeWorkspaceId,
    activeWorkspace ? activeWorkspace.repoPath || activeWorkspace.repo_path : null,
    activeWorkspaceBindingRevision,
  );
  return activeWorkspaceBindingRevision;
}

async function findRegisteredWorkspaceByPath(repoPath) {
  const targetKey = pathService.comparisonKey(repoPath);
  const workspaces = await registry.list();
  return workspaces.find((workspace) => (
    pathService.comparisonKey(workspace.repoPath || workspace.repo_path) === targetKey
  )) || null;
}

async function handleAddRequested(event) {
  const { repoPath, connectionId } = event;

  if (!repoPath || typeof repoPath !== 'string' || !fs.existsSync(repoPath)) {
    console.warn('[WorkspaceController] add_requested: path missing or invalid (' + repoPath + ')');
    return;
  }

  let canonical;
  try {
    canonical = pathService.canonicalize(repoPath);
  } catch (err) {
    console.warn('[WorkspaceController] add_requested: canonicalize failed — ' + err.message);
    return;
  }

  const existing = await findRegisteredWorkspaceByPath(canonical);
  if (existing) {
    emit('workspace:add_rejected_duplicate', {
      existingWorkspace: existing,
      connectionId,
    });
    return;
  }

  const aiPath = path.join(canonical, 'ai');
  if (!isDirectory(aiPath)) {
    emit('workspace:add_rejected_missing_ai', {
      repoPath: canonical,
      connectionId,
    });
    return;
  }

  const id = await generateUniqueId(canonical);
  const label = toTitleCase(path.basename(canonical));
  const nextSortOrder = (await registry.maxSortOrder()) + 1;

  // Detect workspace paradigm: 'app' if ai/apps/ exists, otherwise 'code'
  const hasAppsDir = fs.existsSync(path.join(canonical, 'ai', 'apps'));
  const workspaceType = hasAppsDir ? 'app' : 'code';

  const workspace = await registry.add({
    id,
    label,
    icon: 'folder',
    description: null,
    repoPath: canonical,
    sortOrder: nextSortOrder,
    type: workspaceType,
    ribbonVisible: true,
    ribbonSortOrder: nextSortOrder,
  });

  let viewAvailability = await prepareWorkspaceViews(workspace, { allowViewless: true });
  if (viewAvailability.status !== 'unavailable') {
    try {
      bootstrap.bootstrap(canonical);
    } catch (err) {
      console.warn('[WorkspaceController] add_requested: bootstrap failed — ' + err.message);
      viewAvailability = {
        status: 'unavailable',
        verified: false,
        code: 'view_registry_unavailable',
      };
    }
  }

  emit('workspace:added', {
    workspace,
    viewRegistryUnavailable: viewAvailability.status === 'unavailable',
  });
  emit('workspace:registry_changed', { workspaces: await registry.list() });
}

async function handleSwitchRequested(event) {
  const { workspaceId } = event;
  const target = await registry.getById(workspaceId);
  if (!target) {
    console.warn('[WorkspaceController] switch_requested: unknown workspace (' + workspaceId + ')');
    return;
  }
  if (workspaceId === activeWorkspaceId) return;

  const viewAvailability = await prepareWorkspaceViews(target);

  const from = activeWorkspaceId;
  const bindingRevision = setActiveWorkspace(workspaceId, target);
  await writeLastActive(workspaceId);

  emit('workspace:switched', {
    from,
    to: workspaceId,
    repoPath: target.repo_path,
    bindingRevision,
    viewRegistryUnavailable: viewAvailability.status === 'unavailable',
  });
}

async function handleRemoveRequested(event) {
  const { workspaceId } = event;
  const target = await registry.getById(workspaceId);
  if (!target) {
    console.warn('[WorkspaceController] remove_requested: unknown workspace (' + workspaceId + ')');
    return;
  }

  const wasActive = workspaceId === activeWorkspaceId;
  await viewReadiness.retireWorkspaceViewReadiness(
    {
      workspaceId,
      projectRoot: target.repoPath || target.repo_path,
    },
    () => registry.remove(workspaceId),
  );

  emit('workspace:removed', { workspaceId });
  emit('workspace:registry_changed', { workspaces: await registry.list() });

  if (wasActive) {
    const remaining = await registry.list();
    const next = remaining.length > 0 ? remaining[0] : null;
    const nextId = next ? next.id : null;
    const bindingRevision = setActiveWorkspace(nextId, next);
    await writeLastActive(nextId);
    emit('workspace:switched', {
      from: workspaceId,
      to: nextId,
      repoPath: next ? next.repo_path : null,
      bindingRevision,
    });
  }
}

async function handleCreateRequested(event) {
  const { projectPath, label, connectionId } = event;
  if (!projectPath || typeof projectPath !== 'string' || !path.isAbsolute(projectPath)) {
    rejectCreate(connectionId, 'Create New requires an absolute project path.');
    return;
  }

  const requestedPath = path.resolve(projectPath);
  const parent = path.dirname(requestedPath);
  if (!isDirectory(parent)) {
    rejectCreate(connectionId, 'Parent directory does not exist.');
    return;
  }
  const exactParent = pathService.canonicalize(parent);
  const targetPath = path.join(exactParent, path.basename(requestedPath));
  if (fs.existsSync(targetPath) && !isDirectoryEmpty(targetPath)) {
    rejectCreate(connectionId, 'Project path already exists and is not empty.');
    return;
  }

  const existing = await findRegisteredWorkspaceByPath(targetPath);
  if (existing) {
    rejectCreate(connectionId, 'Project is already registered.');
    return;
  }

  let selectedViews;
  try {
    selectedViews = createService.scaffoldProject({
      projectPath: targetPath,
    }).selectedViews;
  } catch (err) {
    rejectCreate(connectionId, err.message);
    return;
  }

  const canonical = pathService.canonicalize(targetPath);
  const id = await generateUniqueId(canonical);
  const workspaceLabel = String(label || '').trim() || toTitleCase(path.basename(canonical));
  const nextSortOrder = (await registry.maxSortOrder()) + 1;
  const workspace = await registry.add({
    id,
    label: workspaceLabel,
    icon: selectedViews[0]?.icon || 'folder',
    description: null,
    repoPath: canonical,
    sortOrder: nextSortOrder,
    type: 'code',
    ribbonVisible: true,
    ribbonSortOrder: nextSortOrder,
  });

  const viewAvailability = await prepareWorkspaceViews(workspace);

  const from = activeWorkspaceId;
  const bindingRevision = setActiveWorkspace(id, workspace);
  await writeLastActive(id);

  emit('workspace:created', { workspace, connectionId });
  emit('workspace:added', { workspace });
  emit('workspace:registry_changed', { workspaces: await registry.list() });
  emit('workspace:switched', {
    from,
    to: id,
    repoPath: canonical,
    bindingRevision,
    viewRegistryUnavailable: viewAvailability.status === 'unavailable',
  });
}

async function prepareWorkspaceViews(workspace, options = {}) {
  try {
    return await viewReadiness.ensureWorkspaceViewReadiness({
      workspaceId: workspace.id,
      projectRoot: workspace.repoPath || workspace.repo_path,
      allowViewless: options.allowViewless === true,
    });
  } catch (_error) {
    return { status: 'unavailable', verified: false, code: 'view_registry_unavailable' };
  }
}

function rejectCreate(connectionId, message) {
  emit('workspace:create_rejected', {
    connectionId,
    message,
  });
}

function isDirectoryEmpty(targetPath) {
  if (!isDirectory(targetPath)) return false;
  return fs.readdirSync(targetPath).length === 0;
}

async function generateUniqueId(canonicalPath) {
  const base = slugify(path.basename(canonicalPath));
  if (!(await registry.getById(base))) return base;
  let suffix = 2;
  while (await registry.getById(base + '-' + suffix)) {
    suffix += 1;
  }
  return base + '-' + suffix;
}

function slugify(str) {
  return String(str || 'workspace')
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '') || 'workspace';
}

function toTitleCase(str) {
  return String(str || '')
    .replace(/[-_]+/g, ' ')
    .replace(/\b\w/g, (c) => c.toUpperCase())
    .trim() || 'Workspace';
}

function isDirectory(targetPath) {
  try {
    return fs.statSync(targetPath).isDirectory();
  } catch {
    return false;
  }
}

function getActiveWorkspaceId() {
  return activeWorkspaceId;
}

function getActiveWorkspaceBindingRevision() {
  return activeWorkspaceBindingRevision;
}

async function getActiveWorkspace() {
  if (!activeWorkspaceId) return null;
  return registry.getById(activeWorkspaceId);
}

function getActiveWorkspaceSync() {
  return activeWorkspace;
}

async function listWorkspaces() {
  return registry.list();
}

module.exports = {
  start,
  getActiveWorkspaceId,
  getActiveWorkspaceBindingRevision,
  getActiveWorkspace,
  getActiveWorkspaceSync,
  runInWorkspaceLifecycle,
  listWorkspaces,
};

const { EventEmitter } = require('events');
const os = require('os');
const { PassThrough } = require('stream');
const { spawn } = require('child_process');
const { createNativeDiagnosticTap } = require('./native-diagnostic-tap');
const { JsonLineParser } = require('./json-line-parser');
const {
  OpenCodeJsonEventTranslator,
  mapOpenCodeToolName,
  mapOpenCodeTokenUsage,
} = require('./json-event-translator');
const { buildHarnessFailureMarker } = require('./failure-marker-builder');
const { createConfiguredSecretsProvider } = require('./configured-secrets-provider');
const { buildHarnessChildEnvironment } = require('../child-environment');
const { retireSession } = require('./session-retirement');
const { OpenCodeTurnOutcome } = require('./turn-outcome');
const { sanitizeRuntimeHarnessConfig } = require('../../thread/thread-harness-config-policy');
const { logTemporaryChatBoundary } = require('../../logging');

/**
 * Native OpenCode protocol error observation — adapter boundary ONLY
 * (SPEC-03 §A3). Detects the -32004 authentication protocol error in parsed
 * JSON lines so shared runtime code never parses raw provider codes.
 */
function isOpenCodeNativeAuthFailure(event) {
  if (!event || typeof event !== 'object') return false;
  if (event.code === -32004) return true;
  return event.error?.code === -32004;
}

const delay = (ms) => new Promise(resolve => setTimeout(resolve, ms));

function createProcessProxy() {
  const proc = new EventEmitter();
  proc.pid = null;
  proc.stdin = new PassThrough();
  proc.stdout = new PassThrough();
  proc.stderr = new PassThrough();
  proc.killed = false;
  proc.kill = () => {
    proc.killed = true;
    return true;
  };
  return proc;
}

function buildRunArgs(config, projectRoot, openCodeSessionId, message) {
  const args = ['run', '--auto', '--format', 'json'];

  if (projectRoot) {
    args.push('--dir', projectRoot);
  }

  if (config.model) {
    args.push('--model', config.model);
  }

  if (config.variant) {
    args.push('--variant', config.variant);
  }

  if (config.pure === true) {
    args.push('--pure');
  }

  if (config.thinking === true) {
    args.push('--thinking');
  }

  if (openCodeSessionId) {
    args.push('--session', openCodeSessionId);
  }

  args.push(String(message || ''));
  return args;
}

function createSessionIdPatch(openCodeSessionId) {
  return { opencodeSessionId: openCodeSessionId };
}

function getEventSessionId(event) {
  return event?.sessionID || event?.part?.sessionID || null;
}

function createSyntheticTurnEnd(translator) {
  const terminalState = translator.getTerminalState();
  const observedAt = translator.now();
  return {
    type: 'turn_end',
    timestamp: observedAt,
    timestampSource: 'host_observed',
    observedAt,
    reason: 'complete',
    fullText: terminalState.fullText,
    hasToolCalls: terminalState.hasToolCalls,
    _meta: {
      harnessId: 'opencode',
      provider: 'opencode',
      terminalSource: 'process_exit_missing_step_finish',
    },
  };
}

class OpenCodeHarness extends EventEmitter {
  constructor() {
    super();
    this.id = 'opencode';
    this.name = 'OpenCode';
    this.provider = 'opencode';
    this.cliName = 'opencode';
    this.config = {};
    this.sessions = new Map();
    // Default real configured-secrets provider; initialize(config) may
    // override it with config.getConfiguredSecrets (documented injection
    // point for tests/alternative owners).
    this.getConfiguredSecrets = createConfiguredSecretsProvider();
  }

  async initialize(config = {}) {
    this.config = { ...this.config, ...config };
  }

  async startThread(threadId, projectRoot, scopeContext = {}, threadOptions = {}) {
    const harness = this;
    const sessionKey = threadOptions.sessionKey || threadId;
    // The registry owns one adapter instance, but runtime policy is scoped to
    // the workspace that created this session. Capture it now so a later
    // workspace initialization cannot retarget this session's prompts.
    const runtimeConfig = { ...(threadOptions.runtimeConfig || harness.config) };
    const harnessConfig = sanitizeRuntimeHarnessConfig(
      'opencode',
      threadOptions.harnessConfig,
    );
    const storedSessionId = harnessConfig.opencodeSessionId || null;
    const updateHarnessConfig = threadOptions.updateHarnessConfig;
    const session = {
      threadId,
      sessionKey,
      process: createProcessProxy(),
      activeProcess: null,
      activeProcessClose: null,
      openCodeSessionId: storedSessionId,
      stopRequested: false,
      projectRoot,
      scopeContext,
      // Live per-thread config. Mutated by applyHarnessConfig() so mid-thread
      // model/effort changes take effect on the next prompt without a re-spawn.
      harnessConfig,
      applyHarnessConfig(patch) {
        session.harnessConfig = { ...session.harnessConfig, ...patch };
      },
      async *sendMessage(message, options = {}) {
        const translator = new OpenCodeJsonEventTranslator();
        const events = [translator.beginTurn(message)];
        const parser = new JsonLineParser();
        const cliPath = runtimeConfig.cliPath || process.env.OPENCODE_PATH || 'opencode';
        const runConfig = {
          ...runtimeConfig,
          // Live per-thread model + effort override the workspace defaults.
          ...(session.harnessConfig.model ? { model: session.harnessConfig.model } : {}),
          ...(session.harnessConfig.variant ? { variant: session.harnessConfig.variant } : {}),
        };
        const args = buildRunArgs(runConfig, projectRoot, session.openCodeSessionId, message);
        let done = false;
        let sawTurnEnd = false;
        const outcome = new OpenCodeTurnOutcome();
        let sawNativeAuthFailure = false;
        let sawRenderableOutput = false;
        let sawNativeJson = false;
        let sawSessionId = false;
        let sawToolCalls = false;
        let lastTranslatedType = null;
        // SPEC-03 Slice A: exit/close failures are described, then translated
        // into a genuine HarnessRuntimeError marker at throw time (the
        // builder is async). Spawn errors stay raw — they are not one of the
        // three native signals and take the shared generic path unchanged.
        let failureDescriptor = null;
        let spawnFailure = null;
        let stderr = '';
        const envSnapshot = buildHarnessChildEnvironment('opencode', {
          overrides: { TERM: 'xterm-256color' },
        });
        const getConfiguredSecrets = typeof runtimeConfig.getConfiguredSecrets === 'function'
          ? runtimeConfig.getConfiguredSecrets
          : harness.getConfiguredSecrets;
        const diagnosticTap = createNativeDiagnosticTap(options.nativeDiagnostic, {
          getConfiguredSecrets, env: envSnapshot, workspaceRoot: projectRoot || '', homePath: os.homedir(),
        });
        let capturedOpenCodeSessionId = session.openCodeSessionId;
        let capturedSessionIdPatch = null;

        const commitSessionIdPatch = (openCodeSessionId) => {
          session.openCodeSessionId = openCodeSessionId;
        };

        const diagnosticIdentity = { threadId, turnId: options.turnId, harnessId: 'opencode' };
        logTemporaryChatBoundary('spawn_attempt', {
          ...diagnosticIdentity, hadStoredSessionId: Boolean(session.openCodeSessionId),
        });
        let proc;
        let environmentReady = false;
        try {
          // The diagnostic snapshot above has already verified this family and
          // its overrides. Keep spawn's env owned directly by the central
          // builder so the child-launch inventory can verify the boundary.
          environmentReady = true;
          proc = spawn(cliPath, args, {
            stdio: ['ignore', 'pipe', 'pipe'],
            cwd: projectRoot || process.cwd(),
            env: buildHarnessChildEnvironment('opencode', {
              overrides: { TERM: 'xterm-256color' },
            }),
          });
        } catch (err) {
          logTemporaryChatBoundary('spawn_throw', {
            ...diagnosticIdentity, errorCode: err?.code, errorName: err?.name,
            errno: err?.errno, environmentReady,
          });
          diagnosticTap.finish();
          throw err;
        }
        logTemporaryChatBoundary('spawn_return', { ...diagnosticIdentity, pid: proc.pid });

        session.activeProcess = proc;
        session.activeProcessClose = new Promise((resolve) => {
          proc.once('close', resolve);
        });
        session.process = proc;
        session.stopRequested = false;

        parser.on('message', (openCodeEvent, originalLine) => {
          sawNativeJson = true;
          diagnosticTap.push(originalLine);
          if (isOpenCodeNativeAuthFailure(openCodeEvent)) {
            sawNativeAuthFailure = true;
          }
          const openCodeSessionId = getEventSessionId(openCodeEvent);
          if (openCodeSessionId) sawSessionId = true;
          if (!capturedOpenCodeSessionId && openCodeSessionId) {
            const sessionIdPatch = createSessionIdPatch(openCodeSessionId);
            capturedOpenCodeSessionId = openCodeSessionId;
            if (typeof updateHarnessConfig === 'function') {
              capturedSessionIdPatch = sessionIdPatch;
            } else {
              commitSessionIdPatch(openCodeSessionId);
            }
          }

          const translated = translator.translate(openCodeEvent);
          outcome.observe(openCodeEvent, translated);
          for (const event of translated) {
            events.push(event);
            lastTranslatedType = event.type;
            if (event.type === 'content' || event.type === 'thinking') {
              sawRenderableOutput = true;
            }
            if (event.type === 'tool_call' || event.type === 'tool_call_args'
              || event.type === 'tool_result' || event.type === 'tool_snapshot') {
              sawToolCalls = true;
            }
            if (event.type === 'turn_end') {
              sawTurnEnd = true;
            }
          }
        });

        // Malformed lines are recoverable; valid surrounding JSON continues.
        parser.on('parse_error', (line, err, lineNumber) => {
          harness.emit('parse_error', { threadId, line, error: err, lineNumber });
        });

        proc.stdout.on('data', (data) => parser.feed(data.toString()));
        proc.stderr.on('data', (data) => {
          stderr += data.toString();
        });
        proc.on('error', (err) => {
          logTemporaryChatBoundary('spawn_error', {
            ...diagnosticIdentity, pid: proc.pid, errorCode: err?.code,
          });
          if (!session.stopRequested) spawnFailure = err;
          done = true;
        });
        proc.on('close', (code, signal) => {
          parser.flush();
          logTemporaryChatBoundary('child_close', {
            ...diagnosticIdentity, pid: proc.pid, exitCode: code, signal,
            sawNativeJson, sawSessionId, sawTurnEnd,
            stopRequested: session.stopRequested,
          });
          if (session.stopRequested) {
            done = true;
            return;
          }
          if (code !== 0) {
            failureDescriptor = { exitCode: code, signal };
          } else if (!sawTurnEnd && outcome.permitsCleanExitCompletion()) {
            events.push(createSyntheticTurnEnd(translator));
            sawTurnEnd = true;
          } else if (!sawTurnEnd) {
            failureDescriptor = { exitCode: code, signal };
          }
          done = true;
        });
        proc.on('exit', (code, signal) => {
          if (!session.stopRequested && code !== 0 && !sawTurnEnd && !failureDescriptor) {
            failureDescriptor = { exitCode: code, signal };
          }
        });

        try {
          while (!done || events.length > 0) {
            while (events.length > 0) yield events.shift();
            if (!done) await delay(options.pollIntervalMs || 10);
          }
          if (capturedSessionIdPatch && !session.openCodeSessionId) {
            try {
              await updateHarnessConfig(capturedSessionIdPatch);
            } catch (err) {
              logTemporaryChatBoundary('session_patch_error', {
                ...diagnosticIdentity, pid: proc.pid, errorCode: err?.code,
              });
              throw err;
            }
            commitSessionIdPatch(capturedOpenCodeSessionId);
            logTemporaryChatBoundary('session_patch_committed', { ...diagnosticIdentity, pid: proc.pid });
          }
          if (spawnFailure) throw spawnFailure;
          if (failureDescriptor) {
            // SPEC-03 Slice A: translate the native exit signal into a
            // provider-neutral marker AT THE ADAPTER BOUNDARY. The thrown
            // message is fixed internal text; stderr survives only inside
            // the already-redacted candidate.
            throw await buildHarnessFailureMarker({
              nativeAuthFailure: sawNativeAuthFailure,
              stderr,
              nativeDetail: outcome.toolError,
              exitCode: failureDescriptor.exitCode,
              signal: failureDescriptor.signal,
              harnessId: harness.id,
              workspaceRoot: projectRoot || undefined,
              homePath: os.homedir(),
              envSnapshot,
              lastCanonicalEventType: lastTranslatedType || undefined,
              hadRenderableOutput: sawRenderableOutput,
              hadToolCalls: sawToolCalls,
              getConfiguredSecrets,
            });
          }
          if (!session.stopRequested && !session.openCodeSessionId) {
            logTemporaryChatBoundary('missing_session_id', {
              ...diagnosticIdentity, pid: proc.pid, sawNativeJson, sawSessionId,
            });
            // Missing-sessionID stays a generic error by contract (not one of
            // the three native signals; semantics unchanged).
            throw new Error('OpenCode JSON run completed without a sessionID; cannot preserve thread continuity');
          }
        } finally {
          diagnosticTap.finish();
          if (session.activeProcess === proc) {
            session.activeProcess = null;
            session.activeProcessClose = null;
          }
        }
      },
      async stop(signal) {
        await retireSession(harness.sessions, sessionKey, session, signal);
      },
    };

    this.sessions.set(sessionKey, session);
    return session;
  }

  getSession(threadId) {
    const exact = this.sessions.get(threadId);
    if (exact) return exact;
    const matches = [...this.sessions.values()].filter((session) => session.threadId === threadId);
    return matches.length === 1 ? matches[0] : undefined;
  }

  async dispose() {
    for (const session of this.sessions.values()) {
      await session.stop();
    }
    this.sessions.clear();
  }

  async isInstalled() {
    return new Promise((resolve) => {
      const cliPath = this.config.cliPath || process.env.OPENCODE_PATH || 'opencode';
      const proc = spawn(cliPath, ['--version'], {
        stdio: 'pipe',
        env: buildHarnessChildEnvironment('probe'),
      });
      proc.on('error', () => resolve(false));
      proc.on('close', (code) => resolve(code === 0));
      proc.on('exit', (code) => resolve(code === 0));
    });
  }

  async getVersion() {
    return new Promise((resolve, reject) => {
      const cliPath = this.config.cliPath || process.env.OPENCODE_PATH || 'opencode';
      const proc = spawn(cliPath, ['--version'], {
        stdio: 'pipe',
        env: buildHarnessChildEnvironment('probe'),
      });
      let output = '';

      proc.stdout.on('data', (data) => { output += data.toString(); });
      proc.stderr.on('data', (data) => { output += data.toString(); });
      proc.on('error', (err) => reject(new Error(`Failed to run ${cliPath}: ${err.message}`)));
      proc.on('close', (code) => {
        if (code === 0) {
          resolve(output.trim());
        } else {
          reject(new Error(`${cliPath} --version exited with code ${code}`));
        }
      });
    });
  }
}

module.exports = {
  OpenCodeHarness,
  OpenCodeJsonEventTranslator,
  JsonLineParser,
  mapOpenCodeToolName,
  mapOpenCodeTokenUsage,
  createConfiguredSecretsProvider,
  isOpenCodeNativeAuthFailure,
};

/**
 * @module chatScreenshotCapture
 * @role Shared screenshot capture-and-attach controller for header and composer actions.
 */

import { useChatFileLinkStore } from '../state/chatFileLinkStore';
import { usePanelStore } from '../state/panelStore';
import { createSendToChatAttachment } from '../lib/chat-file-links/send-to-chat-reference-label';
import type { ChatLinkAttachment } from '../lib/chat-file-links/file-link-types';
import { showToast } from '../lib/toast';

export const SCREENSHOT_FLASH_EVENT = 'fusion:screenshot-flash';

const CAPTURE_TIMEOUT_MS = 30_000;
const OWNER_CHANGED_MESSAGE = 'Screenshot was not attached because the chat changed.';

export interface ScreenshotAttachmentOwner {
  workspaceId: string;
  threadId: string;
  /** Only the Main Chat owns screenshot attachment; Secondary Chat is retired. */
  surface: 'primary';
}

function currentPrimaryOwner(
  state: ReturnType<typeof usePanelStore.getState>,
): ScreenshotAttachmentOwner | null {
  if (!state.activeWorkspaceId || !state.currentThreadId) return null;
  return {
    workspaceId: state.activeWorkspaceId,
    threadId: state.currentThreadId,
    surface: 'primary',
  };
}

function isCurrentOwner(owner: ScreenshotAttachmentOwner): boolean {
  const state = usePanelStore.getState();
  return state.activeWorkspaceId === owner.workspaceId
    && state.currentThreadId === owner.threadId;
}

function screenshotName(savedPath: string): string {
  return savedPath.split(/[\\/]/).pop() || 'screenshot.png';
}

function waitForSavedScreenshot(
  socket: WebSocket,
  workspaceId: string,
  dataUrl: string,
): Promise<string> {
  const requestId = `screenshot-${Date.now()}-${Math.random().toString(36).slice(2)}`;

  return new Promise((resolve, reject) => {
    const cleanup = () => {
      window.clearTimeout(timeoutId);
      socket.removeEventListener('message', handleMessage);
      socket.removeEventListener('close', handleClose);
    };
    const fail = (message: string) => {
      cleanup();
      reject(new Error(message));
    };
    const handleClose = () => fail('Fusion server disconnected while saving the screenshot.');
    const handleMessage = (event: MessageEvent) => {
      try {
        const message = JSON.parse(event.data) as {
          type?: string;
          requestId?: string;
          savedPath?: string;
          message?: string;
        };
        if (message.requestId !== requestId) return;
        if (message.type === 'screenshot:file-captured' && message.savedPath) {
          cleanup();
          resolve(message.savedPath);
          return;
        }
        if (message.type === 'screenshot:error') {
          fail(message.message || 'The screenshot could not be saved.');
        }
      } catch {
        // Ignore unrelated non-JSON WebSocket traffic.
      }
    };
    const timeoutId = window.setTimeout(() => {
      fail('Timed out while saving the screenshot.');
    }, CAPTURE_TIMEOUT_MS);

    socket.addEventListener('message', handleMessage);
    socket.addEventListener('close', handleClose);

    try {
      socket.send(JSON.stringify({
        type: 'screenshot:file-capture',
        requestId,
        workspaceId,
        dataUrl,
      }));
    } catch (error) {
      fail(error instanceof Error ? error.message : 'The screenshot request could not be sent.');
    }
  });
}

export async function captureAndAttachScreenshot(
  requestedOwner?: ScreenshotAttachmentOwner,
): Promise<ChatLinkAttachment | null> {
  const panelState = usePanelStore.getState();
  // Snapshot the complete owner and socket from one state read before the
  // first await. Composer callers pass their exact Main Chat owner; global
  // capture defaults to the primary owner from this same read.
  const owner = requestedOwner ?? currentPrimaryOwner(panelState);
  const socket = panelState.ws;
  const capturePage = window.electronAPI?.capturePage;

  if (!owner || !isCurrentOwner(owner)) {
    showToast(OWNER_CHANGED_MESSAGE);
    return null;
  }
  if (!capturePage) {
    showToast('Screenshot capture is available in the desktop app.');
    return null;
  }
  if (!socket || socket.readyState !== WebSocket.OPEN) {
    showToast('Fusion must be connected before taking a screenshot.');
    return null;
  }

  try {
    const base64 = await capturePage();
    if (!base64) throw new Error('The current window could not be captured.');
    if (!isCurrentOwner(owner)) {
      showToast(OWNER_CHANGED_MESSAGE);
      return null;
    }

    const dataUrl = `data:image/png;base64,${base64}`;
    window.dispatchEvent(new CustomEvent<string>(SCREENSHOT_FLASH_EVENT, { detail: dataUrl }));

    const savedPath = await waitForSavedScreenshot(socket, owner.workspaceId, dataUrl);
    if (!isCurrentOwner(owner)) {
      showToast(OWNER_CHANGED_MESSAGE);
      return null;
    }
    const name = screenshotName(savedPath);
    const attachment = createSendToChatAttachment({
      panel: 'screenshots',
      relativePath: `Data/Screenshots/${name}`,
      absolutePath: savedPath,
    });

    useChatFileLinkStore.getState().addPendingAttachment(
      owner.workspaceId,
      owner.threadId,
      attachment,
    );

    const currentState = usePanelStore.getState();
    if (currentState.chatActive) {
      currentState.warmThread(owner.threadId);
    }

    showToast('Screenshot attached to chat.');
    return attachment;
  } catch (error) {
    console.error('[ScreenshotCapture] capture-and-attach failed:', error);
    showToast(error instanceof Error ? error.message : 'Screenshot capture failed.');
    return null;
  }
}

'use strict';

const crypto = require('crypto');

const RECORDED_EVENT_TYPES = new Set([
  'workspace:switched',
  'thread:state_changed',
  'file:changed',
]);

const REDACTED_KEYS = new Set([
  'content',
  'contents',
  'fileContent',
  'rawContent',
  'before',
  'after',
  'diff',
]);

const MAX_STRING_LENGTH = 4000;

function isRecordedEventType(type) {
  return RECORDED_EVENT_TYPES.has(type);
}

async function getMachineIdentity(db) {
  const row = await db('system_config').where('key', 'local_machine_name').first();

  return {
    machineId: null,
    machineName: row?.value || null,
  };
}

function inferWorkspaceId(event) {
  return event.workspaceId || event.workspace || event.to || null;
}

function inferActor(event) {
  if (event.actor && typeof event.actor === 'object') {
    return {
      actorType: event.actor.type || event.actor.actorType || 'system',
      actorId: event.actor.id || event.actor.actorId || null,
    };
  }

  return {
    actorType: event.actorType || event.actor_type || (event.type === 'file:changed' ? 'user' : 'system'),
    actorId: event.actorId || event.actor_id || null,
  };
}

function inferSourceModule(event) {
  if (event.sourceModule) return event.sourceModule;
  if (event.source) return event.source;
  if (event.type === 'workspace:switched') return 'workspace-controller';
  if (event.type === 'thread:state_changed') return 'thread-lifecycle-controller';
  if (event.type === 'file:changed') return 'workspace-watcher';
  return null;
}

function buildSummary(event) {
  if (event.summary) return String(event.summary);
  if (event.type === 'workspace:switched') {
    return `Workspace switched from ${event.from || 'none'} to ${event.to || 'none'}`;
  }
  if (event.type === 'thread:state_changed') {
    return `Thread ${event.threadId || 'unknown'} changed state to ${event.state || 'unknown'}`;
  }
  if (event.type === 'file:changed') {
    return `${event.context?.type || 'file'} ${event.event || 'changed'}: ${event.filePath || event.path || 'unknown'}`;
  }
  return event.type;
}

function sanitizePayload(value, seen = new WeakSet()) {
  if (value == null) return value;
  if (typeof value === 'string') {
    return value.length > MAX_STRING_LENGTH
      ? `${value.slice(0, MAX_STRING_LENGTH)}...[truncated]`
      : value;
  }
  if (typeof value !== 'object') return value;
  if (seen.has(value)) return '[circular]';
  seen.add(value);

  if (Array.isArray(value)) {
    return value.map((item) => sanitizePayload(item, seen));
  }

  const clean = {};
  for (const [key, entryValue] of Object.entries(value)) {
    if (REDACTED_KEYS.has(key)) {
      clean[key] = '[redacted]';
    } else {
      clean[key] = sanitizePayload(entryValue, seen);
    }
  }
  return clean;
}

function tagsForEvent(event) {
  const tags = new Set();
  if (Array.isArray(event.tags)) {
    for (const tag of event.tags) {
      if (tag) tags.add(String(tag));
    }
  }
  if (event.type === 'workspace:switched') tags.add('workspace');
  if (event.type === 'thread:state_changed') tags.add('thread');
  if (event.type === 'file:changed') {
    tags.add('resource');
    tags.add(event.event || 'changed');
  }
  return Array.from(tags);
}

function edgesForEvent(event, machineIdentity) {
  const workspaceId = inferWorkspaceId(event);
  const machineId = machineIdentity.machineId;

  if (event.type === 'file:changed') {
    const filePath = event.filePath || event.path || null;
    const resourceType = event.context?.type || event.resourceType || 'file';
    return [{
      resource_type: resourceType,
      resource_id: event.resourceId || filePath,
      workspace_id: workspaceId,
      machine_id: machineId,
      path: filePath,
      role: event.role || 'subject',
    }];
  }

  return [];
}

async function recordEvent(db, event, options = {}) {
  if (!event || !isRecordedEventType(event.type)) return null;

  const now = Date.now();
  const machineIdentity = await getMachineIdentity(db);
  const actor = inferActor(event);
  const eventId = event.eventId || crypto.randomUUID();
  const occurredAt = Number.isFinite(event.timestamp) ? event.timestamp : now;
  const row = {
    event_id: eventId,
    event_type: event.type,
    workspace_id: inferWorkspaceId(event),
    machine_id: machineIdentity.machineId,
    machine_name: machineIdentity.machineName,
    actor_type: actor.actorType || 'system',
    actor_id: actor.actorId,
    occurred_at: occurredAt,
    summary: buildSummary(event),
    payload_json: JSON.stringify(sanitizePayload(event)),
    source_module: inferSourceModule(event),
    correlation_id: event.correlationId || event.correlation_id || null,
    causation_id: event.causationId || event.causation_id || null,
    created_at: now,
  };
  const edges = edgesForEvent(event, machineIdentity);
  const tags = tagsForEvent(event);

  const trxProvider = options.transaction || ((fn) => db.transaction(fn));
  await trxProvider(async (trx) => {
    await trx('event_log').insert(row);
    if (edges.length > 0) {
      await trx('event_resource_edges').insert(edges.map((edge) => ({
        event_id: eventId,
        ...edge,
      })));
    }
    if (tags.length > 0) {
      await trx('event_tags').insert(tags.map((tag) => ({
        event_id: eventId,
        tag,
      })));
    }
  });

  return {
    eventId,
    row,
    edges,
    tags,
  };
}

async function listRecentEvents(db, options = {}) {
  const limit = Math.min(Math.max(Number(options.limit) || 20, 1), 200);
  let query = db('event_log').orderBy('occurred_at', 'desc').limit(limit);
  if (options.eventType) query = query.where('event_type', options.eventType);
  if (options.workspaceId) query = query.where('workspace_id', options.workspaceId);
  if (options.machineId) query = query.where('machine_id', options.machineId);
  return query;
}

module.exports = {
  RECORDED_EVENT_TYPES,
  isRecordedEventType,
  recordEvent,
  listRecentEvents,
};

'use strict';

const { on } = require('../event-bus');
const { performance } = require('perf_hooks');
const { getDb } = require('../db');
const { isRecordedEventType, recordEvent } = require('./event-ledger');

let stopCurrent = null;
const inFlightWrites = new Set();

function startEventLedgerSubscriber(options = {}) {
  if (stopCurrent) return stopCurrent;

  const dbProvider = options.getDb || getDb;
  const logger = options.logger || console;
  const unsubscribe = on('*', (event) => {
    if (!event || !isRecordedEventType(event.type)) return;

    const task = Promise.resolve()
      .then(() => recordEvent(dbProvider(), event))
      .catch((err) => {
        logger.warn('[EventLedger] write failed:', err.message);
      });
    inFlightWrites.add(task);
    task.finally(() => inFlightWrites.delete(task));
    return task;
  });

  stopCurrent = () => {
    unsubscribe();
    stopCurrent = null;
  };

  logger.log('[EventLedger] Subscriber started');
  return stopCurrent;
}

async function drainEventLedgerWrites({
  timeoutMs = 5_000,
  deadline = null,
  monotonicNow = () => performance.now(),
  setTimer = setTimeout,
  clearTimer = clearTimeout,
} = {}) {
  if (stopCurrent) stopCurrent();
  const localDeadline = Math.min(
    monotonicNow() + Math.max(0, timeoutMs),
    Number.isFinite(deadline) ? deadline : Number.POSITIVE_INFINITY,
  );
  while (inFlightWrites.size > 0) {
    const remaining = Math.max(0, localDeadline - monotonicNow());
    if (remaining <= 0) return Object.freeze({ drained: false });
    let timer;
    const completed = await Promise.race([
      Promise.allSettled([...inFlightWrites]).then(() => true),
      new Promise((resolve) => {
        timer = setTimer(() => resolve(false), remaining);
        timer?.unref?.();
      }),
    ]);
    if (timer) clearTimer(timer);
    if (!completed) return Object.freeze({ drained: false });
  }
  return Object.freeze({ drained: true });
}

module.exports = {
  drainEventLedgerWrites,
  startEventLedgerSubscriber,
};

/**
 * Calendar Broadcaster — bus → WebSocket fan-out for calendar sync events.
 * Template: lib/ws/workspace-broadcaster.js. Same shape — subscribe at startup,
 * broadcast to all clients, no state.
 */

const { on } = require('../event-bus');

function createCalendarBroadcaster({ getAllClients }) {
  function broadcastAll(wireMessage) {
    const payload = JSON.stringify(wireMessage);
    for (const ws of getAllClients()) {
      if (ws.readyState !== 1) continue;
      ws.send(payload);
    }
  }

  on('calendar:sync_complete', (event) => {
    broadcastAll({
      type: 'calendar:sync_complete',
      source: event.source,
      calendarCount: event.calendarCount,
      eventCount: event.eventCount,
    });
  });

  console.log('[CalendarBroadcaster] Started');
  return { started: true };
}

module.exports = { createCalendarBroadcaster };
